/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: mount, rows, select, decide, distinct, saved, candidate, several, open, reset
 * Tests
 *   - a single Artist entry is decided on its own row, and the saved decision names that entry and its name
 *   - several entries and a label each get a row in draft order with their roles, and every saved decision names its entry or none
 *   - an Artist another entry already reuses cannot be chosen again, and Organization candidates appear only on the label row
 *   - an append shows entry and label rows as not applied and keeps their stored decisions in the saved set
 *   - decisions of removed entries or tracks are neither shown nor saved
 *   - unsaved decisions survive a newer revision, and become stale once a decided entry or the label is renamed or newer decisions were saved
 *   - automatic values that rename entries at the same revision read the name matches again, so a new entry is offered its reuse
 * @end-catalog */

import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { ImportDuplicates } from './ImportDuplicates';
import type { ImportCandidate, ImportDecision } from './adminApi';
import { artistEntry, detail, entryKey, json, labelEntry, session, slotId, slotTwo, viewer } from './adminFixtures.testSupport';

/** Renders the duplicate panel for one project and returns the save callback. */
function mount(item = detail()) {
  const onSave = vi.fn(), client = new QueryClient(); client.setQueryData(['browser-session'], session);
  render(<QueryClientProvider client={client}><MemoryRouter><ImportDuplicates item={item} disabled={false} onSave={onSave} /></MemoryRouter></QueryClientProvider>);
  return onSave;
}
/** Each decision row's own label text (scope and name), without its select options. */
const rows = () => [...document.querySelectorAll('label')].map(label => [...label.childNodes].filter(node => node.nodeType === Node.TEXT_NODE).map(node => node.textContent).join(''));
const select = (index: number) => screen.getByRole('combobox', { name: `${index} · Decision` }) as HTMLSelectElement;
const decide = (index: number, value: string) => fireEvent.change(select(index), { target: { value } });
const distinct = (scope: ImportDecision['scope'], slot: string | null = null, key: string | null = null, boundName: string | null = null): ImportDecision => ({ scope, slotId: slot, entryKey: key, boundName, action: 'create-distinct', candidateId: null, candidateRevision: null });
/** The body a save sends: the decisions and the revision of the buffer's first edit. */
const saved = (decisions: ImportDecision[], expectedRevision = 1) => ({ expectedRevision, decisions });
const candidate = (kind: ImportCandidate['kind'], id: string, label: string): ImportCandidate => ({ kind, id, label, revision: `${id}-revision`, albumId: null, visibility: 'public', match: 'name', matchedSlotIds: [], automaticReuse: false });
/** Two primaries, one featured entry and a label, as the editor saves them. */
const several = () => {
  const item = detail(); item.draft.album.title = 'Synthetic Album';
  item.draft.album.artists = [{ ...artistEntry('Lorem Ensemble', entryKey(1)), joinPhrase: ' & ' }, artistEntry('Ipsum Quartet', entryKey(2)), artistEntry('Dolor Soloist', entryKey(3), 'featured')];
  item.draft.album.label = labelEntry('Sit Records'); return item;
};
const open = async () => { fireEvent.click(screen.getByRole('button', { name: 'Find matches' })); await screen.findByRole('button', { name: 'Save decisions' }); };
const reset = () => { cleanup(); adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); };
beforeEach(() => { reset(); vi.stubGlobal('fetch', vi.fn(async () => json({ items: [] }))); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('a single Artist entry is decided on its own row, and the saved decision names that entry and its name', async () => {
  const item = detail(); item.draft.album.title = 'Synthetic Album'; item.draft.album.artists = [{ ...artistEntry('Lorem Ensemble'), joinPhrase: ' & ' }];
  const onSave = mount(item); await open();
  expect(rows()).toEqual(['Artist · Lorem Ensemble · Primary', 'Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  decide(1, 'create-distinct'); decide(2, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('album')]));
});

test('several entries and a label each get a row in draft order with their roles, and every saved decision names its entry or none', async () => {
  const onSave = mount(several()); await open();
  expect(rows()).toEqual(['Artist · Lorem Ensemble · Primary', 'Artist · Ipsum Quartet · Primary', 'Artist · Dolor Soloist · Featured', 'Label · Sit Records', 'Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  for (const index of [1, 2, 3, 4, 5]) decide(index, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('artist', null, entryKey(3), 'Dolor Soloist'),
    distinct('label', null, null, 'Sit Records'), distinct('album')]));
  // Only tracks may be skipped.
  expect([...select(1).options].map(option => option.value)).toEqual(['', 'create-distinct']);
  expect([...select(6).options].map(option => option.value)).toEqual(['', 'create-distinct', 'skip']);
});

test('an Artist another entry already reuses cannot be chosen again, and Organization candidates appear only on the label row', async () => {
  const artist = 'a'.repeat(24), label = 'b'.repeat(24), item = several();
  // Defensive: the server refuses two entries with one case-insensitive name, but whenever one Artist is shown on two rows the guard holds.
  item.draft.album.artists[1].name = 'lorem ensemble';
  vi.stubGlobal('fetch', vi.fn(async () => json({ items: [candidate('artist', artist, 'Lorem Ensemble'), candidate('organization', label, 'SIT RECORDS')] })));
  const onSave = mount(item); await open();
  const reuseOption = (index: number, id: string) => [...select(index).options].find(option => option.value === id);
  // Both same-named entries see the Artist; once the first reuses it, the second cannot.
  expect([reuseOption(1, artist)?.disabled, reuseOption(2, artist)?.disabled]).toEqual([false, false]);
  decide(1, artist);
  expect([reuseOption(1, artist)?.disabled, reuseOption(2, artist)?.disabled, reuseOption(3, artist)]).toEqual([false, true, undefined]);
  // The Organization is a candidate of the label row only, and links to its catalog page.
  expect([reuseOption(1, label), reuseOption(4, label)?.disabled]).toEqual([undefined, false]);
  expect(screen.getByRole('link', { name: 'SIT RECORDS' }).getAttribute('href')).toBe(`/admin/catalog/organization/${label}`);
  expect(screen.getAllByRole('link', { name: 'Lorem Ensemble' }).map(link => link.getAttribute('href'))).toEqual([`/admin/catalog/artist/${artist}`, `/admin/catalog/artist/${artist}`]);
  decide(4, label);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([
    { scope: 'artist', slotId: null, entryKey: entryKey(1), boundName: 'Lorem Ensemble', action: 'reuse', candidateId: artist, candidateRevision: `${artist}-revision` },
    { scope: 'label', slotId: null, entryKey: null, boundName: 'Sit Records', action: 'reuse', candidateId: label, candidateRevision: `${label}-revision` }
  ]));
});

test('an append shows entry and label rows as not applied and keeps their stored decisions in the saved set', async () => {
  const album = 'c'.repeat(24), item = several();
  item.decisions = [distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('label', null, null, 'Sit Records'), { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: album, candidateRevision: 'album-revision' }];
  vi.stubGlobal('fetch', vi.fn(async () => json({ items: [candidate('album', album, 'Synthetic Album')] })));
  const onSave = mount(item); await open();
  expect(rows()).toEqual(['Album · Synthetic Album', 'Track · Untitled Album', 'Track · Untitled Album']);
  expect(screen.getAllByText('Not applied: this import adds tracks to an existing Album, so this needs no decision.')).toHaveLength(4);
  // Rows keep their positions: the entries and the label are rows 1 to 4 without a select.
  decide(6, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([...item.decisions, distinct('track', slotId)]));
});

test('decisions of removed entries or tracks are neither shown nor saved', async () => {
  const item = several();
  item.decisions = [distinct('artist', null, entryKey(9), 'Removed Entry'), distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('track', '10000000-0000-4000-8000-0000000000ff'), distinct('track', slotTwo)];
  const onSave = mount(item); await open();
  expect([select(1).value, select(2).value, select(7).value]).toEqual(['', 'create-distinct', 'create-distinct']);
  decide(5, 'create-distinct');
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(2), 'Ipsum Quartet'), distinct('track', slotTwo), distinct('album')]));
});

test('unsaved decisions survive a newer revision, and become stale once a decided entry or the label is renamed or newer decisions were saved', async () => {
  const item = several(); mount(item); await open();
  decide(1, 'create-distinct'); decide(4, 'create-distinct');
  // A later field save, an upload or automatic values from file tags bump the revision without renaming anything: the buffer stays
  // usable, and its save still names the revision of its first edit, so decisions saved since then would conflict.
  cleanup(); const edit = { operationId: '20000000-0000-4000-8000-000000000009', kind: 'edit' as const, revision: item.revision + 2 };
  const onSave = mount({ ...several(), revision: item.revision + 3, valueRevision: 2, receipts: [edit] }); await open();
  expect([select(1).value, select(4).value, screen.queryByRole('alert')]).toEqual(['create-distinct', 'create-distinct', null]);
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledExactlyOnceWith(saved([distinct('artist', null, entryKey(1), 'Lorem Ensemble'), distinct('label', null, null, 'Sit Records')], item.revision));
  // Renaming the decided entry or the label, or another administrator's saved decisions or approval after the first edit, makes
  // the buffer stale: it says so and cannot be saved until the saved decisions are loaded.
  const newer = (kind: 'decisions' | 'publish') => (next: ReturnType<typeof several>) => { next.receipts = [{ operationId: '20000000-0000-4000-8000-00000000000a', kind, revision: item.revision + 1 }]; };
  for (const change of [(next: ReturnType<typeof several>) => { next.draft.album.artists[0].name = 'Lorem Renamed'; }, (next: ReturnType<typeof several>) => { next.draft.album.label = labelEntry('Sit Records Ltd'); }, newer('decisions'), newer('publish')]) {
    cleanup(); const changed = several(); change(changed); changed.revision = item.revision + 4; mount(changed); await open();
    expect(screen.getByRole('alert').textContent).toContain('load saved version');
    expect((screen.getByRole('button', { name: 'Save decisions' }) as HTMLButtonElement).disabled).toBe(true);
  }
});

test('automatic values that rename entries at the same revision read the name matches again, so a new entry is offered its reuse', async () => {
  const artist = 'a'.repeat(24), fetches = vi.fn(async () => json({ items: fetches.mock.calls.length > 1 ? [candidate('artist', artist, 'Tagged Ensemble')] : [] }));
  vi.stubGlobal('fetch', fetches);
  const before = detail(), client = new QueryClient(); client.setQueryData(['browser-session'], session);
  const view = (item: ReturnType<typeof detail>) => <QueryClientProvider client={client}><MemoryRouter><ImportDuplicates item={item} disabled={false} onSave={vi.fn()} /></MemoryRouter></QueryClientProvider>;
  const { rerender } = render(view(before)); await open();
  expect(fetches).toHaveBeenCalledTimes(1);
  // The album step wrote an automatic entry without changing the revision.
  const after = detail(); after.valueRevision = before.valueRevision + 1; after.draft.album.artists = [artistEntry('Tagged Ensemble')]; after.automaticPaths = ['album.artists'];
  rerender(view(after));
  expect(await screen.findByRole('option', { name: /^Reuse existing · Tagged Ensemble/ })).toBeTruthy();
  expect(fetches).toHaveBeenCalledTimes(2);
  expect(String((fetches.mock.calls[1] as unknown[])[0])).toContain('/duplicate-candidates');
});
